function revisionPending(){return {revision:{code:'R1',name:'Design',amount:128600,status:'Chưa kiểm tra đủ',delta:3600}};}
export const metricNames=['Uy tín','Chất lượng','Dư địa thời gian','Năng lực'];
export const freshState=()=>({version:1,index:0,metrics:[45,45,85,25],method:'undecided',flags:[],history:[],revisions:[]});
export function decide(state, index){
 const scene=scenes[state.index];
 if(!scene || !Number.isInteger(index) || !scene.options[index]) throw new Error('Invalid decision');
 const option=scene.options[index], next=structuredClone(state), effects=[...option.effects];
 let boss=option.boss, lesson=option.lesson;
 if(option.controlled && state.method==='2d'){effects[2]-=5;lesson+=' Với 2D, bạn cần thêm công đối chiếu và cập nhật thủ công.';}
 if(option.controlled && ['bim','hybrid'].includes(state.method) && state.flags.includes('system')){effects[2]+=5;lesson+=' Dữ liệu đã chuẩn hóa giúp bạn dành ít thời gian hơn cho thao tác cập nhật.';}
 if(option.requiresEvidence && (!state.flags.includes('baseline') || !state.flags.includes('tenderChecked'))){effects[0]-=8;effects[2]-=8;boss='Hướng giải thích đúng, nhưng lịch sử trước đó còn thiếu. Em phải dựng lại cơ sở và nhờ senior kiểm tra trước khi gửi.';lesson+=' Vì bạn chưa lưu hoặc kiểm tra đủ các mốc trước, việc phục hồi chứng cứ tốn thêm thời gian.';}
 next.metrics=state.metrics.map((value,i)=>Math.max(0,Math.min(100,value+effects[i])));
 if(option.method) next.method=option.method;
 if(option.flag) next.flags.push(option.flag);
 if(option.revision) next.revisions.push({...option.revision});
 const result={scene:state.index,choice:index,title:option.title,boss,client:option.client,lesson,effects:next.metrics.map((v,i)=>v-state.metrics[i])};
 next.history.push(result);next.index++;
 return {state:next,result};
}
export function restore(saved){
 if(!saved || saved.version!==1 || !Array.isArray(saved.history) || saved.history.length>scenes.length) return null;
 let state=freshState();
 try{for(const entry of saved.history) state=decide(state,entry.choice).state;}catch{return null;}
 return state;
}
export function ending(state){
 const [trust,quality,time,skill]=state.metrics;
 if(trust<40 || quality<40) return {title:'Một lần vấp để học cách làm nghề',text:'Đội phải dành thêm thời gian rà soát và sửa kỳ vọng. Hãy chơi lại, tập trung vào đầu vào, review và giải thích thay đổi trước khi cam kết.',rank:'Cần củng cố nền tảng'};
 if(trust>=75 && quality>=75 && time>=25 && skill>=70 && state.flags.includes('growth')) return {title:'Từ người ra số đến cộng sự đáng tin',text:state.method==='2d'?'Bạn chứng minh được dự toán động có thể được quản lý bằng 2D với kỷ luật cập nhật. Cơ hội tiếp theo là giảm công thủ công bằng dữ liệu và công cụ phù hợp.':'Bạn kết hợp được hiểu thi công, dữ liệu và công cụ. Đội tin bạn hơn vì có thể giải thích, kiểm tra và phản ứng với thay đổi.',rank:'Sẵn sàng dẫn dắt một gói pilot'};
 if(time<30) return {title:'Giữ được chất lượng, nhưng đang quá tải',text:'Bạn đã bảo vệ được kết quả bằng nhiều công sức. Hãy đầu tư vào cấu trúc dữ liệu, phân công review và công cụ phù hợp để tăng dư địa khi revision dày hơn.',rank:'Cần cải thiện hiệu suất'};
 return {title:'Một Junior đang trưởng thành',text:'Bạn đã có những quyết định tốt và một số khoảng trống cần khắc phục. Xem lại nhật ký để chọn một thói quen cụ thể cho dự án tiếp theo.',rank:'Tiếp tục tích lũy năng lực'};
}
